function loadEndeavorContext() {
  // First-officer coordinates the endeavor — they must see its shape. Other
  // offices get their work via dispatch and don't need this overview.
  if (process.env.FARS_OFFICE !== 'first-officer') return '';

  const lines = ['## Endeavor Context', ''];

  // Charter Function — the thing all work serves
  try {
    if (fs.existsSync(CHARTER_FILE)) {
      const charter = fs.readFileSync(CHARTER_FILE, 'utf8');
      const funcMatch = charter.match(/## I\. Function\s*\n+The endeavor of.*?\*\*([^*]+)\*\*/s);
      if (funcMatch) {
        lines.push(`**Function (from charter):** the pursuit of ${funcMatch[1]}.`);
        lines.push('');
      }
    }
  } catch { /* skip */ }

  // Active projects — the architectural decomposition
  try {
    if (fs.existsSync(PROJECTS_DIR)) {
      const projectFiles = fs.readdirSync(PROJECTS_DIR)
        .filter(f => f.endsWith('.md') && !f.startsWith('_'));
      const projects = [];
      for (const f of projectFiles) {
        try {
          const content = fs.readFileSync(path.join(PROJECTS_DIR, f), 'utf8');
          const fm = parseFrontmatter(content);
          if (fm.status && fm.status !== 'active') continue;
          projects.push({
            id: fm.id || f.replace('.md', ''),
            title: fm.title || fm.id || f.replace('.md', ''),
            goal: fm.goal || '',
          });
        } catch { /* skip */ }
      }
      if (projects.length > 0) {
        lines.push(`**Active projects (${projects.length}) — the computer system decomposition:**`);
        for (const p of projects) {
          lines.push(`- \`${p.id}\` — ${p.title.replace(/^["']|["']$/g, '')}`);
        }
        lines.push('');
      }
    }
  } catch { /* skip */ }

  // Open objectives serving goals
  try {
    const ds = require('./datastore.js');
    const db = ds.load();
    const openObjs = (db.query({ type: 'objective', status: 'open' }) || []).slice(0, 8);
    if (openObjs.length > 0) {
      lines.push(`**Open objectives (${openObjs.length} shown) — concrete work targets:**`);
      for (const o of openObjs) {
        const title = (o.title || o.id || '').slice(0, 100);
        lines.push(`- ${title}`);
      }
      lines.push('');
    }
  } catch { /* skip */ }

  lines.push('*Coordinate work against these, not in isolation. See /bridge for the operational view.*');
  lines.push('');

  return lines.length > 4 ? lines.join('\n') : '';
}

