const fs = require('fs');
const path = require('path');
const { COMMAND_DIR } = require('./operations/engineering/fars/agentic/lib/repo-paths');

const subdirs = ['tasks', 'plans', 'objectives', 'goals', 'projects', 'directives'];
const byType = {};

function parseStatus(content) {
  const m = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return null;
  const sm = m[1].match(/^status:\s*(\S+)/m);
  return sm ? sm[1].replace(/[\"']/g, '') : null;
}

function parseType(content) {
  const m = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return null;
  const tm = m[1].match(/^type:\s*(\S+)/m);
  return tm ? tm[1].replace(/[\"']/g, '') : null;
}

for (const sub of subdirs) {
  const dir = path.join(COMMAND_DIR, 'records', sub);
  if (!fs.existsSync(dir)) continue;
  for (const f of fs.readdirSync(dir)) {
    if (!f.endsWith('.md') || f.startsWith('_')) continue;
    const content = fs.readFileSync(path.join(dir, f), 'utf8');
    const status = parseStatus(content);
    const type = parseType(content) || sub.slice(0, -1);
    if (!status) continue;
    byType[type] = byType[type] || {};
    byType[type][status] = (byType[type][status] || 0) + 1;
  }
}

