{"command":"node -e "
const fs = require('fs');
const path = require('path');
const { COMMAND_DIR } = require('./operations/engineering/fars/agentic/lib/repo-paths');

// Canonicalization rules by entity type. Drawn from work-state-machine.js.
const RULES = {
  task: { 'done': 'completed' },
  plan: { 'open': 'active' },
};

function parseType(content) {
  const m = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return null;
  const tm = m[1].match(/^type:\s*(\\S+)/m);
  return tm ? tm[1].replace(/[\"']/g, '') : null;
}

const dryRun = process.argv.includes('--apply') ? false : true;
let changed = 0;

function scan(dir, typeHint) {
  if (!fs.existsSync(dir)) return;
  for (const f of fs.readdirSync(dir)) {
    if (!f.endsWith('.md') || f.startsWith('_')) continue;
    const fpath = path.join(dir, f);
    let content = fs.readFileSync(fpath, 'utf8');
    const type = parseType(content) || typeHint;
    const rules = RULES[type];
    if (!rules) continue;
    let modified = false;
    for (const [from, to] of Object.entries(rules)) {
      const pattern = new RegExp('^(status:\\\\s*)' + from + '(\\\\s*)$', 'm');
      if (pattern.test(content)) {
        content = content.replace(pattern, '\$1' + to + '\$2');
        modified = true;
        console.log((dryRun ? '[dry] ' : '[fix] ') + path.relative('.', fpath) + ': ' + type + '.status ' + from + ' → ' + to);
      }
    }
    if (modified) {
      changed++;
      if (!dryRun) fs.writeFileSync(fpath, content);
    }
  }
}

scan(path.join(COMMAND_DIR, 'records', 'tasks'), 'task');
scan(path.join(COMMAND_DIR, 'records', 'plans'), 'plan');
console.log('\n' + (dryRun ? 'Would change ' : 'Changed ') + changed + ' files');
