/**
 * canonicalize-status.js — Enforce status-value canonicalization across entities.
 *
 * work-state-machine.js defines the canonical status vocabulary per entity type.
 * When entity files drift (someone writes `done` instead of `completed`), this
 * tool rewrites them to canonical values. The canonical vocabulary is loaded
 * from the state machine, not hard-coded here — changing the machine changes
 * what's canonical.
 *
 * The captain pointed out: "plans say 'done' and 'complete' and nothing cares
 * about the difference." This tool is what cares.
 *
 * Usage:
 *   node canonicalize-status.js             # dry-run, show what would change
 *   node canonicalize-status.js --apply     # rewrite files in place
 *   node canonicalize-status.js --audit     # just count status values by type
 *   node canonicalize-status.js --json      # JSON output
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { COMMAND_DIR } = require('../lib/repo-paths');
const sm = require('./work-state-machine.js');

// Synonym rules per entity type. Maps non-canonical values to canonical ones.
// Every synonym MUST map to a value that appears in sm.MACHINES[type].states.
const SYNONYMS = {
