 *   As CLI:   node work-state-machine.js                        # Show all machines
 *             node work-state-machine.js task                    # Show task machine
 *             node work-state-machine.js task open               # Show valid transitions from open
 *             node work-state-machine.js validate task open completed  # Check if transition is valid
 */
'use strict';

const fs = require('fs');
const path = require('path');

const MACHINES_PATH = path.join(__dirname, '..', 'data', 'work-state-machines.json');
const MACHINES = JSON.parse(fs.readFileSync(MACHINES_PATH, 'utf8'));
