function canTransition(entityType, fromState, toState) {
  const machine = MACHINES[entityType];
  if (!machine) return false;
  return machine.transitions.some(t => t.from === fromState && t.to === toState);
}

function getTransition(entityType, fromState, toState) {
  const machine = MACHINES[entityType];
  if (!machine) return null;
  return machine.transitions.find(t => t.from === fromState && t.to === toState) || null;
}

function validNextStates(entityType, fromState) {
  const machine = MACHINES[entityType];
  if (!machine) return [];
  return [...new Set(machine.transitions.filter(t => t.from === fromState).map(t => t.to))];
}

function isTerminal(entityType, state) {
  const machine = MACHINES[entityType];
  if (!machine) return false;
  return machine.terminal.includes(state);
}

function allStates(entityType) {
  const machine = MACHINES[entityType];
  if (!machine) return [];
  return Object.keys(machine.states);
}

function eventForTransition(entityType, fromState, toState) {
  const t = getTransition(entityType, fromState, toState);
  return t ? t.event : null;
}

